import axios from "axios";

const BASE_URL = "http://127.0.0.1:8001";

async function sendImage(endpoint, formData) {
  try {
    const response = await axios.post(`${BASE_URL}${endpoint}`, formData, {
      headers: {
        "Content-Type": "multipart/form-data",
      },
      responseType: "blob",
    });
    return await blobToBase64(response.data);
  } catch (e) {
    console.error("İstek sırasında hata oluştu:", e);
    return null;
  }
}

function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

export const cropImageRequest = (formData) => sendImage("/cropImage/", formData);
export const grayScaleRequest = (formData) => sendImage("/grayScale/", formData);
export const binaryRequest = (formData) => sendImage("/binaryDonusum/", formData);
export const rotateRequest = (formData) => sendImage("/rotate/", formData);
export const brightnessRequest = (formData) => sendImage("/brightness/", formData);
export const sobelRequest = (formData) => sendImage("/sobel/", formData);
export const zoomInRequest = (formData) => sendImage("/zoomIn/", formData);
export const blurringRequest = (formData) => sendImage("/blurring/", formData);
export const gaussRequest = (formData) => sendImage("/gauss/", formData);
export const adaptifEsiklemeRequest = (formData) => sendImage("/adaptifesikleme/", formData);
export const gurultuEklemeRequest = (formData) => sendImage("/gurultuekleme/", formData);
export const gurultuTemizlemeRequest = (formData) => sendImage("/gurultuTemizleme/", formData);
